package com.bank.status.service;

import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Sorts characters by decreasing frequency via a max-heap on frequency.
public class StatusReportService {
    private static final Logger log = Logger.getLogger(StatusReportService.class.getName());

    public String sortByFrequency(String codes) {
        Map<Character, Integer> freq = new HashMap<>();
        for (char c : codes.toCharArray()) freq.merge(c, 1, Integer::sum);
        PriorityQueue<Character> maxHeap = new PriorityQueue<>((a, b) -> freq.get(b) - freq.get(a));
        maxHeap.addAll(freq.keySet());
        StringBuilder sb = new StringBuilder();
        while (!maxHeap.isEmpty()) {
            char c = maxHeap.poll();                 // most frequent remaining
            for (int i = 0; i < freq.get(c); i++) sb.append(c);
        }
        String result = sb.toString();
        log.info(() -> "Frequency-sorted codes = " + result);
        return result;
    }
}
